<template>
  <div>
    <button @click="toggleView">{{ showCheckout ? 'View Lessons' : 'View Cart' }} ({{ cart.length }})</button>
    <component :is="showCheckout ? 'CheckoutComponent' : 'LessonComponent'" :lessons="lessons" :cart="cart" @add-item-to-cart="addItemToCart" @remove-item-from-cart="removeItemFromCart"></component>
  </div>
</template>

<script>
import LessonComponent from './LessonComponent.vue'
import CheckoutComponent from './CheckoutComponent.vue'
import axios from 'axios'

export default {
  components: {
    LessonComponent,
    CheckoutComponent
  },
  data() {
    return {
      showCheckout: false,
      lessons: [],
      cart: []
    }
  },
  methods: {
    toggleView() {
      this.showCheckout = !this.showCheckout;
    },
    addItemToCart(lesson) {
      const item = this.cart.find(i => i.id === lesson.id);
      if (item) {
        item.quantity++;
      } else {
        this.cart.push({ ...lesson, quantity: 1 });
      }
    },
    removeItemFromCart(lesson) {
      const index = this.cart.findIndex(i => i.id === lesson.id);
      if (index !== -1) {
        if (this.cart[index].quantity > 1) {
          this.cart[index].quantity--;
        } else {
          this.cart.splice(index, 1);
        }
      }
    },
    fetchLessons() {
      axios.get('/PWA/lessons.json')
        .then(response => {
          this.lessons = response.data;
        })
        .catch(error => {
          console.error("Error fetching lessons:", error);
        });
    }
  },
  created() {
    this.fetchLessons();
  }
}
</script>
